def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    threshold_voltage = parameters[0] - parameters[1] * gate_voltage_abs + parameters[2] * drain_voltage_abs
    transconductance = parameters[3] * np.exp(parameters[4] * (gate_voltage_abs - parameters[5])) * np.exp(parameters[6] * (drain_voltage_abs - parameters[7]))
    return 10 * np.log10(np.abs(transconductance * np.exp(threshold_voltage)))
